#!/usr/bin/env node
/**
 * Export contract ABIs from Foundry build output into typed TypeScript consts for the app
 * (viem's `as const` ABIs give full type inference for reads/writes/events).
 *
 *   cd contracts && forge build && node scripts/export-abi.mjs
 *
 * Writes:
 *   src/lib/contracts/registryAbi.ts         — `export const registryAbi = [...] as const`
 *   src/lib/contracts/guardedTreasuryAbi.ts  — `export const guardedTreasuryAbi = [...] as const`
 *
 * Only ABIs are exported (no bytecode) so the generated files stay small and diff-friendly.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const contractsDir = resolve(here, "..");
const repoRoot = resolve(contractsDir, "..");
const outDir = resolve(contractsDir, "out");
const targetDir = resolve(repoRoot, "src/lib/contracts");

/** @type {Array<{ artifact: string; exportName: string; file: string; doc: string }>} */
const TARGETS = [
  {
    artifact: "AttestationRegistry.sol/AttestationRegistry.json",
    exportName: "registryAbi",
    file: "registryAbi.ts",
    doc: "ABI of contracts/src/AttestationRegistry.sol (includes the ICompliR read interface).",
  },
  {
    artifact: "GuardedTreasury.sol/GuardedTreasury.json",
    exportName: "guardedTreasuryAbi",
    file: "guardedTreasuryAbi.ts",
    doc: "ABI of contracts/src/examples/GuardedTreasury.sol (reference integrator).",
  },
];

/** Deterministic ordering so re-running on an unchanged build produces no diff. */
function sortAbi(abi) {
  const kindOrder = { constructor: 0, error: 1, event: 2, function: 3, fallback: 4, receive: 5 };
  return [...abi].sort((a, b) => {
    const k = (kindOrder[a.type] ?? 9) - (kindOrder[b.type] ?? 9);
    if (k !== 0) return k;
    const an = a.name ?? "";
    const bn = b.name ?? "";
    if (an !== bn) return an < bn ? -1 : 1;
    // Overloads: order by input signature.
    const sig = (x) => (x.inputs ?? []).map((i) => i.type).join(",");
    return sig(a) < sig(b) ? -1 : sig(a) > sig(b) ? 1 : 0;
  });
}

function header(doc, artifact) {
  return [
    "// AUTO-GENERATED by contracts/scripts/export-abi.mjs — do not edit by hand.",
    `// Source artifact: contracts/out/${artifact}`,
    `// ${doc}`,
    "",
  ].join("\n");
}

if (!existsSync(outDir)) {
  console.error(`export-abi: ${outDir} not found. Run \`forge build\` in contracts/ first.`);
  process.exit(1);
}
mkdirSync(targetDir, { recursive: true });

for (const t of TARGETS) {
  const artifactPath = resolve(outDir, t.artifact);
  if (!existsSync(artifactPath)) {
    console.error(`export-abi: missing artifact ${artifactPath} (run \`forge build\`).`);
    process.exit(1);
  }
  const json = JSON.parse(readFileSync(artifactPath, "utf8"));
  if (!Array.isArray(json.abi)) {
    console.error(`export-abi: ${artifactPath} has no "abi" array.`);
    process.exit(1);
  }
  const abi = sortAbi(json.abi);
  const body = `${header(t.doc, t.artifact)}export const ${t.exportName} = ${JSON.stringify(abi, null, 2)} as const;\n`;
  const outPath = resolve(targetDir, t.file);
  writeFileSync(outPath, body);
  console.log(`export-abi: wrote ${outPath} (${abi.length} entries)`);
}
